import socket
from threading import Event
from lab_common import local_server
selesai = Event()

def diam(conn):
    # Server sudah menerima koneksi, tetapi menunggu client selesai.
    if not selesai.wait(timeout=2):
        raise TimeoutError('Demo tidak menyelesaikan sinkronisasi.')

if __name__ == '__main__':
    with local_server(diam) as alamat:
        try:
            with socket.create_connection(alamat, timeout=1) as client:
                client.settimeout(.1)
                try:
                    client.recv(16)
                except TimeoutError:
                    print('Batas waktu baca tercapai')
        finally:
            selesai.set()
    print('Timeout tidak sama dengan bukti perangkat mati')

import json

def proses(payload):
    if len(payload) > 4096:
        raise ValueError('Pesan terlalu besar.')
    pesan = json.loads(payload.decode('utf-8'))
    if not isinstance(pesan, dict) or set(pesan) != {'id', 'aksi'}:
        raise ValueError('Kolom wajib tepat id dan aksi.')
    if type(pesan['id']) is not int or not 1 <= pesan['id'] <= 9999 or pesan['aksi'] != 'ping':
        raise ValueError('ID atau aksi tidak valid.')
    return {'id': pesan['id'], 'hasil': 'pong'}

if __name__ == '__main__':
    payload = json.dumps({'id': 7, 'aksi': 'ping'}).encode('utf-8')
    print('Balasan:', proses(payload))
    try:
        proses(b'{"id":true,"aksi":"ping"}')
    except ValueError:
        print('ID boolean ditolak')

import json
import socket
from lab_common import local_server, send_frame, recv_frame

PERANGKAT = {'BTS-LAB': {'status': 'up', 'rtt_ms': 12}}

def jawab(payload):
    request = json.loads(payload.decode('utf-8'))
    if not isinstance(request, dict) or set(request) != {'id', 'aksi', 'perangkat'}:
        raise ValueError('Skema permintaan tidak sesuai.')
    if type(request['id']) is not int or not 1 <= request['id'] <= 9999:
        raise ValueError('ID wajib integer 1..9999.')
    if request['aksi'] != 'status' or not isinstance(request['perangkat'], str):
        raise ValueError('Hanya aksi status dengan nama perangkat teks.')
    data = PERANGKAT.get(request['perangkat'])
    return {'id': request['id'], 'ok': data is not None, 'data': data}

def layani(conn):
    payload = recv_frame(conn)
    try:
        response = jawab(payload)
    except (ValueError, UnicodeError):
        response = {'ok': False, 'error': 'permintaan_invalid'}
    send_frame(conn, json.dumps(response).encode('utf-8'))

if __name__ == '__main__':
    with local_server(layani) as alamat:
        with socket.create_connection(alamat, timeout=2) as client:
            request = {'id': 21, 'aksi': 'status', 'perangkat': 'BTS-LAB'}
            send_frame(client, json.dumps(request).encode('utf-8'))
            response = json.loads(recv_frame(client).decode('utf-8'))
            if response.get('id') != request['id']:
                raise ValueError('ID balasan tidak cocok.')
    print('Balasan:', response)
    print('Data fiktif; layanan hanya membaca status')
